package com.example.evcharging.finance.reconciliation;
import com.example.evcharging.framework.api.ApiResponse;import com.example.evcharging.framework.context.RequestContext;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/admin-api/v1/finance/reconciliation") public class ReconciliationAdminController {private final ReconciliationApplicationService service;private final JdbcTemplate jdbc;public ReconciliationAdminController(ReconciliationApplicationService s,JdbcTemplate j){service=s;jdbc=j;}@PostMapping("/run") public ApiResponse<ReconciliationApplicationService.RunResult> run(@RequestBody ReconciliationApplicationService.RunRequest r){return ApiResponse.ok(service.run(r));}@GetMapping("/batches") public ApiResponse<List<BatchView>> batches(@RequestParam(defaultValue="50")int limit){long t=RequestContext.requireTenantId();return ApiResponse.ok(jdbc.query("SELECT batch_no,channel,merchant_id,business_date,status,local_count,channel_count,match_count,difference_count,completed_time FROM finance_reconciliation_batch WHERE tenant_id=? ORDER BY id DESC LIMIT ?",(rs,n)->new BatchView(rs.getString(1),rs.getString(2),rs.getString(3),String.valueOf(rs.getObject(4)),rs.getString(5),rs.getInt(6),rs.getInt(7),rs.getInt(8),rs.getInt(9),String.valueOf(rs.getObject(10))),t,Math.max(1,Math.min(limit,200))));}@GetMapping("/differences") public ApiResponse<List<DifferenceView>> differences(@RequestParam(defaultValue="OPEN")String status){long t=RequestContext.requireTenantId();return ApiResponse.ok(jdbc.query("SELECT case_no,difference_type,status,reason,resolution,create_time,resolved_time FROM finance_difference_case WHERE tenant_id=? AND status=? ORDER BY id DESC LIMIT 200",(rs,n)->new DifferenceView(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),String.valueOf(rs.getObject(6)),String.valueOf(rs.getObject(7))),t,status.toUpperCase()));}@PostMapping("/differences/{caseNo}/resolve") public ApiResponse<Map<String,String>> resolve(@PathVariable String caseNo,@RequestBody ResolveRequest r){long t=RequestContext.requireTenantId(),u=RequestContext.currentUserId().orElse(0L);LocalDateTime now=LocalDateTime.now();int n=jdbc.update("UPDATE finance_difference_case SET status='RESOLVED',resolution=?,resolved_by=?,resolved_time=?,update_time=? WHERE tenant_id=? AND case_no=? AND status='OPEN'",r.resolution(),u,now,now,t,caseNo);return ApiResponse.ok(Map.of("result",n==1?"RESOLVED":"NO_CHANGE"));}public record ResolveRequest(String resolution){}public record BatchView(String batchNo,String channel,String merchantId,String businessDate,String status,int localCount,int channelCount,int matchCount,int differenceCount,String completedTime){}public record DifferenceView(String caseNo,String differenceType,String status,String reason,String resolution,String createTime,String resolvedTime){}
}
